  if (flag('AUDIT_LOG_TO_STDOUT', true)) { try { console.log(`[feedback-loop:audit] ${JSON.stringify(record)}`); } catch (e) { /* best effort */ } }
  if (!SANDBOX_MODE) {
    try {
      const sd = $getWorkflowStaticData('global');
      const size = Math.max(0, Math.min(2000, num('AUDIT_RING_BUFFER_SIZE', 200)));
