const isoOr = (v, fallback) => { const d = v === undefined || v === null || v === '' ? null : new Date(typeof v === 'number' && v < 1e12 ? v * 1000 : v); return d && !isNaN(d.getTime()) ? d.toISOString() : (fallback || new Date().toISOString()); };

const contacts = $('Outbound Suppression Sync').all().map((i) => i.json).filter((j) => j.kind === 'contact');
const persist = $input.first().json || {};
const run = (contacts[0] || {}).run || {};
const tally = (f) => contacts.reduce((m, c) => { const k = f(c); m[k] = (m[k] || 0) + 1; return m; }, {});
const audit = {
  record: 'feedback_sync_run', at: new Date().toISOString(), runId: run.runId || null, mode: run.mode || null, origin: run.origin || null,
  summary: { contacts: contacts.length, bySeverity: tally((c) => c.severity), unsubscribe: tally((c) => (c.hubspot || {}).unsubscribeState || 'not_requested'),
    hubspot: (contacts.find((c) => c.hubspotStats) || {}).hubspotStats || null, outbound: (contacts.find((c) => c.outboundStats) || {}).outboundStats || null,
    webhookAnswer: (contacts[0] || {}).response ? (contacts[0].response.summary || null) : null },
  persistence: { simulated: !!persist.simulated, suppressionUpserts: Number(persist.suppression_upserts || 0), syncRows: Number(persist.sync_rows || 0),
    eventsUpdated: Number(persist.events_updated || 0), error: persist.error ? redactString(persist.error.message || persist.error).slice(0, 300) : null },
  contacts: contacts.map((c) => ({ ref: c.emailRef, severity: c.severity, reasons: c.reasons, sources: c.sources, retry: !!c.retry,
    hubspot: (c.hubspot || {}).status || null, unsubscribe: (c.hubspot || {}).unsubscribeState || null,
    sendgrid: (c.outbound || {}).sendgrid || null, ses: (c.outbound || {}).ses || null, webhook: (c.outbound || {}).webhook || null })),
