// ─────────────────────────────────────────────────────────────────────
// Node: Sanitized Error Handler              Mode: Run Once for All Items
// Fed by the Error Trigger when this workflow is its own Error Workflow.
// Drops stack traces and request options, redacts secrets, and emits a
// safe alert record (and optionally a minimal Slack notice).
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);
const isPlaceholder = (v) => /^YOUR_[A-Z0-9_]*$/i.test(String(v || '').trim());
const real = (key, fallback = '') => { const v = env(key, ''); return v === '' || isPlaceholder(v) ? fallback : v; };
const KNOWN_SECRETS = ['HUBSPOT_ACCESS_TOKEN', 'SENDGRID_API_KEY', 'SENDGRID_WEBHOOK_PUBLIC_KEY', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'AWS_SESSION_TOKEN',
  'POSTFIX_WEBHOOK_SECRET', 'OUTBOUND_WEBHOOK_SECRET', 'OUTBOUND_SUPPRESSION_WEBHOOK_URL', 'POSTGRES_URL', 'EMAIL_HASH_PEPPER', 'SLACK_WEBHOOK_URL']
  .map((k) => env(k, '')).filter((v) => v.length >= 8 && !isPlaceholder(v));
const SECRET_KEY = /(authorization|token|secret|password|passwd|api[-_]?key|cookie|signature|webhook[-_]?url|subscribeurl|credential)/i;
const redactString = (input) => {
  let s = String(input ?? '');
  for (const secret of KNOWN_SECRETS) s = s.split(secret).join('[REDACTED]');
  s = s.replace(/(postgres(?:ql)?:\/\/[^:\s\/]+:)[^@\s]+@/gi, '$1[REDACTED]@');
  return s
    .replace(/\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{4,}/g, '[REDACTED_JWT]')
    .replace(/Basic\s+[A-Za-z0-9+\/]{8,}=*/gi, 'Basic [REDACTED]')
    .replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/AWS4-HMAC-SHA256\s+Credential=[^\s"']+/gi, 'AWS4-HMAC-SHA256 [REDACTED]')
    .replace(/\b(AKIA|ASIA)[A-Z0-9]{16}\b/g, '[REDACTED_AWS_KEY_ID]')
    .replace(/\bSG\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}\b/g, '[REDACTED_SENDGRID_KEY]')
    .replace(/\bpat-[a-z0-9]{2,6}-[A-Za-z0-9-]{8,}\b/gi, '[REDACTED_HUBSPOT_TOKEN]')
    .replace(/-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, '[REDACTED_PRIVATE_KEY]')
    .replace(/https:\/\/hooks\.slack\.com\/[^\s"']+/gi, '[REDACTED_SLACK_WEBHOOK]')
    .replace(/([?&](?:api_key|apikey|key|token|secret|signature|sig|password|x-amz-signature|x-amz-credential|x-amz-security-token)=)[^&\s"']+/gi, '$1[REDACTED]')
    .replace(/\b([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g, '$1***@$2')
    .slice(0, 1000);
